-- Forge RP report types: six report boards with their form fields and rules,
-- plus the shared red report notice. Generated from report-types.json.
-- Safe to re-run: a board whose slug already exists is left untouched.
-- Apply with: psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f report-types.sql
BEGIN;
INSERT INTO boards (id, slug, name, description, settings, access, created_at, updated_at)
SELECT gen_random_uuid(), 'skarha-na-hravtsia', 'Скарга на гравця', 'Порушення правил іншим гравцем.', '{"customFields": [{"key": "character_name", "label": "Ім’я вашого ігрового персонажа", "type": "text", "required": true, "placeholder": "Henry Forge"}, {"key": "static_id", "label": "Ваш статичний ID", "type": "text", "required": true, "placeholder": "#3", "helpText": "Прицільтеся на гравця: у правому нижньому куті екрана видно Статичний (С:#ID) і Динамічний (Д:#ID). Потрібен статичний.", "pattern": {"regex": "^#?\\d+$", "message": "Вкажіть лише номер, наприклад #3."}}, {"key": "offender_ids", "label": "Статичний ID порушника(-ів)", "type": "id_list", "required": true, "placeholder": "#1, #12"}, {"key": "incident_at", "label": "Дата та час порушення", "type": "datetime", "required": true, "warnOlderThanHours": 48, "warnMessage": "З моменту порушення минуло понад 48 годин: скаргу може бути відхилено."}, {"key": "timecodes", "label": "Тайм-коди порушень", "type": "long_text", "required": true, "placeholder": "1:53 порушення PG, 2:22 порушення PG", "helpText": "Вкажіть моменти відео, на яких зафіксовано порушення."}, {"key": "evidence_url", "label": "Посилання на докази", "type": "url", "required": true, "placeholder": "https://youtu.be/…", "helpText": "Відеозаписи та скріншоти, що дають повне розуміння ситуації. Відеодокази мають бути опубліковані на YouTube.", "warnDomains": ["youtube.com", "youtu.be"], "warnMessage": "Це не посилання на YouTube: скаргу може бути відхилено."}], "rulesMarkdown": "### Корисна інформація\n\nПрицільтеся на порушника: у правому нижньому куті екрана ви побачите Статичний (С:#ID) і Динамічний (Д:#ID).\n\n### Правила подання скарг\n\n1. Заборонено видаляти або приховувати докази, додані до скарги, протягом 72 годин після її розгляду.\n2. Мінімальна тривалість відеозапису повинна становити 5 хвилин або повністю охоплювати ситуацію, на яку подається скарга. У разі недотримання цієї вимоги скаргу може бути відхилено.\n\n### Скаргу може бути відхилено, якщо:\n\n1. Скаргу оформлено не за встановленою формою.\n2. Надані докази були обрізані, відредаговані або змінені будь-яким чином.\n3. З моменту порушення минуло понад 48 годин.\n4. Відеозапис не містить звукового супроводу гри або запису мікрофона гравця.\n5. Якість відеозапису нижча за 720p.\n6. Докази записані від третьої особи. Відеозапис або скріншот повинні бути зроблені від імені автора скарги.\n7. До відеозапису не додано тайм-коди із зазначенням моментів, на яких зафіксовано порушення.\n8. Відеодокази не опубліковані через відеохостинг YouTube.\n\n### Приклад\n\n1. Henry Forge #3.\n2. #1.\n3. PG, гравець не проявляв ознак страху за життя персонажа.\n4. 15:13 03.06.\n5. 1:53 порушення PG, 2:22 порушення PG.\n6. Докази провини гравця: «посилання»."}'::jsonb, '{"kind": "reports", "view": "anonymous", "vote": "team", "comment": "authenticated", "submit": "authenticated", "segments": {"view": [], "vote": [], "comment": [], "submit": []}, "moderation": {"anonPosts": "inherit", "signedPosts": "inherit", "comments": "inherit"}, "replyPolicy": "author-only"}'::jsonb, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM boards WHERE slug = 'skarha-na-hravtsia' AND deleted_at IS NULL);
INSERT INTO boards (id, slug, name, description, settings, access, created_at, updated_at)
SELECT gen_random_uuid(), 'bah-report', 'Баг-репорт', 'Помилка в грі.', '{"customFields": [{"key": "character_name", "label": "Ім’я вашого ігрового персонажа", "type": "text", "required": true, "placeholder": "Henry Forge"}, {"key": "static_id", "label": "Ваш статичний ID", "type": "text", "required": true, "placeholder": "#3", "pattern": {"regex": "^#?\\d+$", "message": "Вкажіть лише номер, наприклад #3."}}, {"key": "evidence_url", "label": "Скріншот або запис багу", "type": "url", "required": true, "placeholder": "https://…"}, {"key": "timecodes", "label": "Тайм-коди", "type": "long_text", "required": false, "helpText": "Якщо додаєте відео, вкажіть моменти, де видно баг."}], "rulesMarkdown": "### Правила подачі баг-репортів\n\n1. Ім’я вашого ігрового персонажа та статичний #ID.\n2. Максимально детальний опис багу. Що ви робили? У якій послідовності?\n3. Скріншот або запис багу з вказаними тайм-кодами."}'::jsonb, '{"kind": "reports", "view": "anonymous", "vote": "team", "comment": "authenticated", "submit": "authenticated", "segments": {"view": [], "vote": [], "comment": [], "submit": []}, "moderation": {"anonPosts": "inherit", "signedPosts": "inherit", "comments": "inherit"}, "replyPolicy": "author-only"}'::jsonb, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM boards WHERE slug = 'bah-report' AND deleted_at IS NULL);
INSERT INTO boards (id, slug, name, description, settings, access, created_at, updated_at)
SELECT gen_random_uuid(), 'skarha-na-administratsiiu', 'Скарга на адміністрацію / апеляція', 'Оскарження покарання або скарга на дії адміністратора.', '{"customFields": [{"key": "static_id", "label": "Ваш статичний ID", "type": "text", "required": true, "placeholder": "#3", "pattern": {"regex": "^#?\\d+$", "message": "Вкажіть лише номер, наприклад #3."}}, {"key": "admin_nickname", "label": "Нікнейм адміністратора, який видав покарання", "type": "text", "required": true}, {"key": "ticket_number", "label": "Номер тікету, за яким вас покарано", "type": "text", "required": false}, {"key": "evidence_url", "label": "Докази", "type": "url", "required": true, "helpText": "Докази, які доводять, що покарання видано помилково. Відеодокази мають бути опубліковані на YouTube.", "warnDomains": ["youtube.com", "youtu.be"], "warnMessage": "Це не посилання на YouTube: звернення може бути відхилено."}], "rulesMarkdown": "### Подача апеляції\n\n1. Вкажіть ваш статичний #ID.\n2. Вкажіть нікнейм адміністратора, який видав покарання.\n3. Вкажіть номер тікету, за яким вас було покарано.\n4. Надайте докази, які доводять, що адміністратор видав покарання помилково."}'::jsonb, '{"kind": "reports", "view": "team", "vote": "team", "comment": "authenticated", "submit": "authenticated", "segments": {"view": [], "vote": [], "comment": [], "submit": []}, "moderation": {"anonPosts": "inherit", "signedPosts": "inherit", "comments": "inherit"}, "replyPolicy": "author-only"}'::jsonb, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM boards WHERE slug = 'skarha-na-administratsiiu' AND deleted_at IS NULL);
INSERT INTO boards (id, slug, name, description, settings, access, created_at, updated_at)
SELECT gen_random_uuid(), 'zaiavka-na-rpk', 'Заявка на РПК', 'Заявка на РПК згідно з правилами РПК.', '{"customFields": [{"key": "static_id", "label": "Ваш статичний ID", "type": "text", "required": true, "placeholder": "#3", "pattern": {"regex": "^#?\\d+$", "message": "Вкажіть лише номер, наприклад #3."}}, {"key": "victim_id", "label": "Статичний ID гравця (жертви РПК)", "type": "id_list", "required": true, "placeholder": "#12"}, {"key": "evidence_url", "label": "Докази згідно з правилами РПК", "type": "url", "required": true, "warnDomains": ["youtube.com", "youtu.be"], "warnMessage": "Це не посилання на YouTube: заявку може бути відхилено."}], "rulesMarkdown": "### Подача заявки на РПК\n\n1. Вкажіть ваш статичний #ID.\n2. Статичний #ID гравця (жертви РПК).\n3. Опишіть ситуацію, яка призвела до створення тікету, згідно з правилами РПК.\n4. Надайте докази згідно з правилами РПК."}'::jsonb, '{"kind": "reports", "view": "team", "vote": "team", "comment": "authenticated", "submit": "authenticated", "segments": {"view": [], "vote": [], "comment": [], "submit": []}, "moderation": {"anonPosts": "inherit", "signedPosts": "inherit", "comments": "inherit"}, "replyPolicy": "author-only"}'::jsonb, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM boards WHERE slug = 'zaiavka-na-rpk' AND deleted_at IS NULL);
INSERT INTO boards (id, slug, name, description, settings, access, created_at, updated_at)
SELECT gen_random_uuid(), 'konsultatsiia-rp', 'Консультація щодо РП-процесів', 'Питання щодо рольових процесів.', '{"customFields": [{"key": "static_id", "label": "Ваш статичний ID", "type": "text", "required": true, "placeholder": "#3", "pattern": {"regex": "^#?\\d+$", "message": "Вкажіть лише номер, наприклад #3."}}], "rulesMarkdown": "Якщо ви не змогли знайти відповідь в Ігрових правилах, максимально детально опишіть ваш запит, і ми намагатимемося вам допомогти."}'::jsonb, '{"kind": "reports", "view": "team", "vote": "team", "comment": "authenticated", "submit": "authenticated", "segments": {"view": [], "vote": [], "comment": [], "submit": []}, "moderation": {"anonPosts": "inherit", "signedPosts": "inherit", "comments": "inherit"}, "replyPolicy": "author-only"}'::jsonb, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM boards WHERE slug = 'konsultatsiia-rp' AND deleted_at IS NULL);
INSERT INTO boards (id, slug, name, description, settings, access, created_at, updated_at)
SELECT gen_random_uuid(), 'inshe', 'Інше', 'Інші запити, наприклад зміна дати народження персонажа.', '{"customFields": [{"key": "static_id", "label": "Ваш статичний ID", "type": "text", "required": true, "placeholder": "#3", "pattern": {"regex": "^#?\\d+$", "message": "Вкажіть лише номер, наприклад #3."}}], "rulesMarkdown": "Якщо ви не змогли знайти відповідь в Ігрових правилах, максимально детально опишіть ваш запит, і ми намагатимемося вам допомогти.\n\n### Приклад: невірна дата народження\n\n1. Вкажіть ваш статичний #ID.\n2. Вкажіть поточну дату народження персонажа.\n3. Вкажіть бажану дату народження персонажа."}'::jsonb, '{"kind": "reports", "view": "team", "vote": "team", "comment": "authenticated", "submit": "authenticated", "segments": {"view": [], "vote": [], "comment": [], "submit": []}, "moderation": {"anonPosts": "inherit", "signedPosts": "inherit", "comments": "inherit"}, "replyPolicy": "author-only"}'::jsonb, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM boards WHERE slug = 'inshe' AND deleted_at IS NULL);
UPDATE settings SET portal_config = (coalesce(nullif(portal_config,''),'{}')::jsonb || jsonb_build_object('reportNotice', '**Усі тікети, оформлені не за встановленою формою подання, можуть бути відхилені адміністрацією без розгляду.**

**Перед подачею тікету переконайтеся, що ви уважно прочитали Ігрові правила.**'))::text;
-- Drop the cached workspace settings so the notice shows without a restart.
DELETE FROM kv_store WHERE key = 'settings:workspace';
COMMIT;
